#include <stdio.h>
#include <stdlib.h>

/*
 * Compute the binomial coefficient C(n, k) using recursion with memoisation.
 * The program accepts exactly two command‑line arguments: n and k.
 * It validates the input and prints one of the following messages:
 *   NO_INPUT      – fewer than two arguments were supplied
 *   BAD_INPUT     – either argument is not a valid integer
 *   OUT_OF_RANGE  – n is negative or greater than 60
 * Otherwise it prints the value of C(n, k) as a signed 64‑bit integer.
 */

#define MAX_N 60

static long memo[MAX_N + 1][MAX_N + 1];
static unsigned char computed[MAX_N + 1][MAX_N + 1];

static long binom(int n, int k)
{
    /* base cases */
    if (k == 0 || k == n)
        return 1;
    if (k < 0 || n < k)
        return 0;

    if (computed[n][k])
        return memo[n][k];

    long v = binom(n - 1, k - 1) + binom(n - 1, k);
    memo[n][k] = v;
    computed[n][k] = 1;
    return v;
}

int main(int argc, char *argv[])
{
    if (argc < 3) {
        puts("NO_INPUT");
        return 0;
    }

    char *end1, *end2;
    long n = strtol(argv[1], &end1, 10);
    long k = strtol(argv[2], &end2, 10);

    /* Bad input if conversion failed or extra characters remain */
    if (end1 == argv[1] || *end1 != '\0' || end2 == argv[2] || *end2 != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    if (n < 0 || n > MAX_N) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    long result = binom((int)n, (int)k);
    printf("%lld\n", result);
    return 0;
}
